#import "../../../template.typ": *
#import "../support.typ": *

#let slide_05() = slide[
  #slide-head("05", [Pending Forces State Into the Encode Operation])

  #v(0.45em)

  #thesis(
    [Any value needed after `Pending` must be owned by the suspended operation. In this design, that owner is `T::Encode`.],
    fill: green-soft,
    accent: green,
    size: 9.9pt,
  )

  #v(0.55em)

  #grid(columns: (1fr, auto, 1fr), gutter: 8pt, align: horizon)[
    #soft-card(
      [Before: split suspended state],
      [
        #align(center)[#text(size: 9.3pt, weight: "bold", fill: orange)[driver retains pieces while codec is `Pending`]]
        #v(0.35em)
        #grid(columns: (1fr,), gutter: 4pt)[
          #flow-step([message/item outside operation], fill: white, accent: gray, size: 7.1pt)
        ][
          #flow-step([temporary destination buffer], fill: orange-soft, accent: orange, size: 7.1pt)
        ][
          #flow-step([progress scattered through driver + encoder], fill: red-soft, accent: red, size: 7.0pt)
        ]
        #v(0.25em)
        #align(center)[#text(size: 7.1pt, fill: ink-soft)[Cancellation, retry, and completion have no single owner.]]
      ],
      fill: orange-soft,
      accent: orange,
      body-size: 8pt,
    )
  ][
    #align(center)[
      #text(size: 7.4pt, fill: palette.muted)[move the suspendable lifetime]
      #v(0.2em)
      #arrow
    ]
  ][
    #soft-card(
      [After: one object Tonic stores],
      [
        #align(center)[#text(size: 9.3pt, weight: "bold", fill: blue)[`T::Encode` owns everything it needs to resume]]
        #v(0.35em)
        #grid(columns: (1fr,), gutter: 4pt)[
          #flow-step([start one owned future], fill: white, accent: blue, size: 7.1pt)
        ][
          #flow-step([driver stores `in_flight: Option<T::Encode>`], fill: blue-soft, accent: blue, size: 6.9pt)
        ][
          #flow-step([`Ready` returns completed `EncodeBuffer`], fill: green-soft, accent: green, size: 6.9pt)
        ]
      ],
      fill: blue-soft,
      accent: blue,
      body-size: 8pt,
    )
  ]

  #v(0.55em)

  #block(width: 100%, inset: (x: 10pt, y: 8pt), radius: 11pt, fill: panel-fill, stroke: 0.45pt + panel-stroke)[
    #grid(columns: (auto, 1fr), gutter: 7pt, align: horizon)[
      #rect(width: 3pt, height: 14pt, radius: 999pt, fill: blue)
    ][
      #text(size: 9pt, weight: "bold", fill: palette.title)[Inside the `T::Encode` object Tonic stores]
    ]
    #v(0.45em)
    #block(width: 100%, inset: (x: 10pt, y: 7pt), radius: 9pt, fill: blue-soft, stroke: 0.35pt + blue)[
      #grid(columns: (1fr, 1fr, 1fr), gutter: 5pt)[
        #chip([message], fill: white, accent: blue)
      ][
        #chip([`EncodeBuffer`], fill: white, accent: blue)
      ][
        #chip([`Prost PollEncodeState`], fill: violet-soft, accent: violet, size: 7.0pt)
      ][
        #chip([DSA/IAX copy state], fill: orange-soft, accent: orange)
      ][
        #chip([descriptor/completion], fill: red-soft, accent: red)
      ][
        #chip([drop/cancel state], fill: green-soft, accent: green)
      ]
    ]
  ]

  #v(1fr)
  #speaker[Once encoding can suspend, the API design question is where the suspended state lives.]
]

